mapper.select:
SELECT sr.outbound_request_id, Pt.partner_name AS brandName, M.member_name AS requestUserName, sr.outbound_date, CASE WHEN sr.approved_status = 'APPROVED' THEN 'approved' WHEN sr.approved_status = 'PENDING' THEN '승인대기' WHEN sr.approved_status = 'COMPANION' THEN '반려' ELSE sr.approved_status END AS approved_status FROM OutboundRequest sr INNER JOIN Member M ON sr.member_id = M.member_id INNER JOIN Partner Pt ON M.partner_id = Pt.partner_id WHERE sr.member_id = #{memberId}
AND ( (sr.approved_status = 'APPROVED' AND #{status} = 'approved') OR (sr.approved_status = 'PENDING' AND #{status} = '승인대기') OR (sr.approved_status = 'COMPANION' AND #{status} = '반려') )
ORDER BY sr.outbound_request_id DESC

SELECT sr.outbound_request_id, p.partner_name AS brandName, m.member_name AS requestUserName, sr.outbound_date, CASE WHEN sr.approved_status = 'APPROVED' THEN 'approved' WHEN sr.approved_status = 'PENDING' THEN '승인대기' WHEN sr.approved_status = 'COMPANION' THEN '반려' ELSE sr.approved_status END AS approved_status FROM OutboundRequest sr INNER JOIN Member m ON sr.member_id = m.member_id INNER JOIN Partner p ON p.partner_id = m.partner_id WHERE m.member_id = #{memberId}
AND sr.approved_status = #{status}
ORDER BY sr.outbound_request_id DESC

