UPDATE OutboundRequest
SET
outbound_address = #{dto.outboundAddress},
requested_delivery_date = #{dto.requestedDeliveryDate}
WHERE outbound_request_id = #{outboundRequestId}
AND member_id = #{memberId}

UPDATE OutboundItem
SET
product_id = #{item.productId},
outbound_quantity = #{item.outboundQuantity}
WHERE outbound_item_id = #{item.outboundItemId}
AND outbound_request_id = #{outboundRequestId}

